public class OrderService {
    private static final Logger log = LoggerFactory.getLogger(OrderService.class);
    private final OrderRepository repository;

    public Order processOrder(Long orderId) throws OrderProcessingException {
        try {
            // Fail-fast validation
            Objects.requireNonNull(orderId, "orderId cannot be null");

            var order = repository.findById(orderId)
                .orElseThrow(() -> new OrderNotFoundException(orderId));

            // Process order...
            return order;

        } catch (DatabaseException e) {
            // Wrap with context, preserve cause
            throw new OrderProcessingException("Failed processing order " + orderId, e);
        }
        // Never catch Exception blindly
        // Never log.error(e.getMessage()) — loses stack trace
        // Never empty catch {} — swallows the problem
    }
}

public class CustomerService {
    private final CustomerRepository repository;

    // WRONG: Using exception for control flow
    public boolean existsWrong(Long id) {
        try {
            repository.findById(id).orElseThrow();
            return true;
        } catch (NoSuchElementException e) {
            return false;  // Expected case, not exceptional
        }
    }

    // RIGHT: Use Optional for expected absence
    public boolean existsRight(Long id) {
        return repository.findById(id).isPresent();
    }

    // RIGHT: Explicit null check
    public void processCustomer(Customer customer) {
        if (customer == null) {
            return;  // Fast path, no exception overhead
        }
        // ... process customer
    }
}

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class FileProcessingService {
    private static final Logger log = LoggerFactory.getLogger(FileProcessingService.class);

    public void processFile(String filePath) {
        try {
            var content = Files.readString(Path.of(filePath));
            // Process content...

        } catch (FileNotFoundException e) {
            // WARN: expected condition in some scenarios
            log.warn("File not found: {}", filePath, e);

        } catch (IOException e) {
            // ERROR: unexpected failure, pass exception as second arg
            log.error("Failed reading file: {}", filePath, e);
            throw new FileProcessingException("Cannot process " + filePath, e);
        }

        // WRONG: log.error(e.getMessage()) — loses stack trace
        // WRONG: log.error("Error: " + e) — no parameterized logging
    }
}

// WRONG: Log-and-rethrow anti-pattern
public class OrderService {
    private static final Logger log = LoggerFactory.getLogger(OrderService.class);

    public Order processOrder(Long id) throws OrderException {
        try {
            return repository.findById(id).orElseThrow();
        } catch (DataAccessException e) {
            log.error("Database error", e);  // First log
            throw new OrderException("Failed", e);  // Propagates up
        }
    }
}

// RIGHT: Let it propagate, log at top
public class OrderService {
    public Order processOrder(Long id) throws OrderException {
        try {
            return repository.findById(id).orElseThrow();
        } catch (DataAccessException e) {
            // Add context, don't log — propagate to boundary
            throw new OrderException("Failed processing order " + id, e);
        }
    }
}

public class CustomerService {
    private final CustomerRepository repository;

    // WRONG: Catching NPE hides the bug
    public String getNameWrong(Long id) {
        try {
            Customer customer = repository.findById(id);
            return customer.getName();  // NPE if customer is null
        } catch (NullPointerException e) {
            return "Unknown";  // Masks the real problem
        }
    }

    // RIGHT: Use Optional for nullable returns
    public String getNameRight(Long id) {
        return repository.findById(id)  // Returns Optional<Customer>
            .map(Customer::getName)
            .orElse("Unknown");
    }

    // RIGHT: Fail-fast validation at entry point
    public void updateCustomer(Customer customer) {
        Objects.requireNonNull(customer, "customer cannot be null");
        // ... safe to use customer here
    }
}

public class OrderService {
    private final OrderRepository repository;

    public Order createOrder(Long customerId, List<String> items, BigDecimal total) {
        // Fail-fast: validate all preconditions at entry
        Objects.requireNonNull(customerId, "customerId cannot be null");
        Objects.requireNonNull(items, "items cannot be null");
        Objects.requireNonNull(total, "total cannot be null");

        if (items.isEmpty()) {
            throw new IllegalArgumentException("Order must have at least one item");
        }

        if (total.compareTo(BigDecimal.ZERO) <= 0) {
            throw new IllegalArgumentException("Total must be positive, got: " + total);
        }

        // All inputs valid — safe to proceed
        var order = new Order(customerId, items, total);
        return repository.save(order);
    }
}
